    const gr = g.createRadialGradient(64, 64, 2, 64, 64, 63);
    gr.addColorStop(0, `rgba(${r},${gC},${b},1)`); gr.addColorStop(0.35, `rgba(${r},${gC},${b},.45)`); gr.addColorStop(1, `rgba(${r},${gC},${b},0)`);
