      for (let i = 0; i < 26; i++) { g.fillStyle = `rgba(${110 + r() * 40 | 0},${55 + r() * 20 | 0},${20},${0.25 + r() * 0.4})`; g.beginPath(); g.ellipse(r() * 256, r() * 192, 6 + r() * 26, 4 + r() * 14, 0, 0, 7); g.fill(); }
      graffiti(g, r, 10, 40, 236, 130);
