  if (ch.an === 2) { aL = aR = 0.05; ch.body.rotation.z = Math.sin(time * 0.7) * 0.03; }
  if (mode === 1) { aL = aR = -1.45 + Math.sin(time * 22) * 0.12; ch.body.rotation.x = 0.28; }
