    m.visible = true; m.position.set(q.x, 0, q.z); m.rotation.y = q.ry;
    // ¿me pilla? (en coordenadas del coche)
    const dx = me.x - q.x, dz = me.z - q.z, along = dx * q.dx + dz * q.dz, side = Math.abs(dx * q.dz - dz * q.dx), d = Math.hypot(dx, dz);
