// mesas de la terraza: x, z de la mesa y hacia dónde mira quien se sienta
const TABLES = [[0.7, 7.5, -PI / 2], [3.3, 7.5, -PI / 2], [5.9, 7.5, -PI / 2], [-6.4, 7.5, -PI / 2]];
