    return R(T('u_mk_buy', nm, pr) + ' · ' + T('u_mk_have', W.ing[it.i] | 0), true, () => { W.cash = r2(W.cash - it.p); W.ing[it.i] = (W.ing[it.i] | 0) + it.n; ev('mart', 0, 0, n); });
