  const should = !!(W && W.vs && W.vs.r === NET.myId && W.ph === 'play') && ride.offT <= 0;
  if (should && !ride.on) { ride.on = true; ride.spd = 0; ride.look = 0; me.x = W.vs.x; me.z = W.vs.z; me.yaw = W.vs.y; me.pitch = -0.08; cut.on = false; AU.play('reload'); }
