  BK.front = new THREE.Mesh(BK.geo, new THREE.MeshLambertMaterial({ side: THREE.FrontSide })); BK.back = new THREE.Mesh(BK.geo, new THREE.MeshLambertMaterial({ side: THREE.BackSide }));
