  for (let i = 0; i < a.count; i++) { const x = b[i * 3], u = x / PW, t = th + Math.sin(th) * 0.55 * u * u; a.array[i * 3] = Math.cos(t) * x; a.array[i * 3 + 2] = Math.sin(t) * x * 0.92; }
